-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "ptBR" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.rogue.dps.Name"] = "DPS corpo a corpo"
L["rm.era.rogue.dps.Description"] = "Níveis 1–60, todas as especializações, também em reinos Hardcore e Autossuficientes; montada a partir do simulador, Icy Veins e Wowhead. Em Furtividade: Premeditação, Emboscar com uma adaga quando o alvo não está de frente para você, Golpe Baixo quando solo, Garrote fora de raides. Em combate: Ripostar, Retalhar a partir de um ponto de combo quando estiver ausente em um elite ou em um alvo com bastante vida (renovado com cinco pontos nos seus três últimos segundos), Expor Armadura com cinco pontos em grupo quando você tem Expor Armadura Aprimorado 2/2 e ninguém usa Fender Armadura, um Eviscerar de dois pontos em um alvo prestes a morrer, senão Eviscerar com cinco e nenhum gerador além de cinco. O gerador segue o que você conhece: Golpe Fantasmagórico e Hemorragia fora de raides, Punhalada pelas Costas com uma adaga quando o alvo não está de frente para você, senão Golpe Sinistro. Lembretes: venenos em cada arma (Veneno Mortal em uma arma de mão secundária, quando você a carregar), Chute, Chá de Cardo, Rajada de Lâminas e Adrenalina em elites ou contra dois inimigos com Retalhar ativo, Sangue Frio com cinco, Evasão quando solo e ferido. Sumir, Esfaquear, Preparação, Golpe no Rim e habilidades raciais vêm listados como desativados; Finta, Disparada, Cegar, Aturdir e o posicionamento ficam com você."
L["rm.era.rogue.dps.simulator.Name"] = "Espadas, Golpe Sinistro sincronizado com o ataque automático (simulador)"
L["rm.era.rogue.dps.simulator.Description"] = "A ordem de Combate “suada” do simulador para Especialização em Espada, uma alternativa à rotação integrada de DPS corpo a corpo recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Golpe Sinistro só logo após um golpe da mão principal (2,0 segundos ou mais até o próximo, ajustado para uma espada de velocidade 2,6–2,8; altere isso duplicando a rotação), a menos que a energia esteja quase cheia ou o alvo prestes a morrer, para que o ataque extra da espada não atrase seu golpe. Eviscerar com cinco também espera por Retalhar, energia cheia ou um alvo morrendo. No resto, como a rotação integrada recomendada."
L["rm.era.rogue.dps.warcrafttavern.Name"] = "DPS corpo a corpo, finalizadores de cinco pontos (Warcraft Tavern)"
L["rm.era.rogue.dps.warcrafttavern.Description"] = "O método da Warcraft Tavern, uma alternativa à rotação integrada de DPS corpo a corpo recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Todo finalizador espera cinco pontos de combo para que Golpes Implacáveis o reembolse. Retalhar é usado a partir do seu segundo grau (nível 42) quando ausente ou acabando, senão Eviscerar; nada de Retalhar com poucos pontos, nada de Eviscerar em alvo quase morto e nada de Expor Armadura (o Fender Armadura de um guerreiro cobre isso). As mesmas aberturas, geradores e lembretes da rotação integrada recomendada."
L["rm.forever.rogue.dps.Name"] = "DPS corpo a corpo"
L["rm.forever.rogue.dps.Description"] = "Dano corpo a corpo para todas as especializações de Ladino do nível 1 ao 60, montado a partir da Icy Veins, Wowhead e Warcraft Tavern. O gerador segue o que você conhece: Mutilar (Golpe Sinistro para o quinto ponto), Hemorragia, Punhalada pelas Costas quando o alvo não está de frente para você, senão Golpe Sinistro. Em Furtividade, abre com Premeditação, Golpe Baixo quando solo, Garrote para Subterfúgio em elites de grupo, senão Emboscar ou Garrote. Mantém Retalhar e Peçonha ativos, usa Expor Armadura em grupo contra elites quando nenhum guerreiro tem cinco Fender Armadura, depois gasta cinco pontos em Ruptura (Subterfúgio, lutas longas) ou Eviscerar, e nunca gera além de cinco. Lembretes: venenos em cada arma, Chute, Rajada de Lâminas e Adrenalina em grupos de inimigos e elites, Sangue Frio, Evasão, Finta, Chá de Cardo e Preparação. Fica com você: Sumir, Disparada, Golpe no Rim, Cegar, Aturdir e o posicionamento. O Forever restringe os dados de combate, então o Rotation Master lista esta rotação integrada como referência e ainda não a seleciona automaticamente."
L["rm.forever.rogue.subtlety.warcrafttavern.Name"] = "Subterfúgio, build de Emboscar (Warcraft Tavern)"
L["rm.forever.rogue.subtlety.warcrafttavern.Description"] = "A build de Subterfúgio Emboscar/Perfídia da Warcraft Tavern: Premeditação e Emboscar em toda abertura, Emboscar de novo sempre que Perfídia permitir, Punhalada pelas Costas pelas costas como gerador (Hemorragia quando o alvo está de frente para você), Golpe Fantasmagórico sempre que sair do tempo de recarga, e Retalhar e depois Eviscerar com cinco pontos, sem Ruptura. Lembra você de usar Sumir para outro Emboscar em um chefe tanqueado. Escolha esta em vez da rotação integrada recomendada de Ladino se você pegou os talentos de Perfídia; ela se aplica com Subterfúgio como sua árvore de talentos principal e Perfídia talentada. Os mesmos lembretes de venenos e tempos de recarga da rotação integrada recomendada. Uma alternativa à rotação integrada de DPS de Ladino recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela."
L["rm.forever.rogue.subtlety.wowhead.Name"] = "Subterfúgio, build de Garrote (Wowhead)"
L["rm.forever.rogue.subtlety.wowhead.Description"] = "O Subterfúgio da Wowhead: Premeditação e Garrote em toda abertura, e Sumir (depois Preparação) usados na rotação para abrir de novo com Garrote quando o último tiver expirado. Retalhar mantido, Expor Armadura em grupo, Ruptura como finalizador de cinco pontos, Hemorragia como único gerador. Isso gasta Sumir, sua fuga, em dano: escolha-a de propósito. Ela se aplica com Subterfúgio como sua árvore de talentos principal, Ações Sujas talentado e Premeditação conhecida. Os mesmos lembretes de venenos e tempos de recarga da rotação integrada recomendada. Uma alternativa à rotação integrada de DPS de Ladino recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela."
L["rm.mop.rogue.assassination.Name"] = "Recomendada"
L["rm.mop.rogue.assassination.Description"] = "Recomendada para Assassinato, do nível 10 ao 90 (simulador e Wowhead para a Fase 5, com os passos de evolução de nível da Icy Veins). Abre a partir da Furtividade com Golpe Baixo quando solo, senão Mutilar (Liquidar com Ponto Cego, com uma adaga). Mantém Retalhar ativo (Envenenar o renova a partir do nível 60) e Ruptura no alvo, gasta cinco pontos em Envenenar enquanto Ruptura durar e quatro pontos para manter o bônus de Envenenar ativo quando você não tem Antecipação, depois Marcado para Morrer, Liquidar abaixo de 35% ou com Ponto Cego (exige uma adaga na mão principal), e Mutilar. Contra quatro ou mais inimigos lutando com você: Retalhar, Tempestade Carmesim com sete inimigos, Ruptura, Envenenar e Leque de Facas; aplicar Ruptura em outros alvos fica por sua conta. Solo, acrescenta Recobrar e um Golpe no Rim quando você está com pouca vida. Lembretes: venenos, Chute, Vendeta em lutas longas, Lâminas Sombrias com Vendeta, Sumir e Preparação durante Vendeta, Passo Furtivo à distância, Evasão quando solo. Fica com você: Truques do Ofício e Expor Armadura (listados, mas desativados), Finta, Disparada e o posicionamento."
L["rm.mop.rogue.assassination.icyveins.Name"] = "Envenenar com cinco (Icy Veins)"
L["rm.mop.rogue.assassination.icyveins.Description"] = "Desativada por padrão. A ordem da Icy Veins e da Method: Sumir assim que sair do tempo de recarga para um Mutilar em furtividade, Vendeta assim que sair do tempo de recarga quando a luta for longa o bastante, Envenenar só com cinco pontos, Ruptura mantida, Liquidar abaixo de 35% ou com Ponto Cego, Mutilar. De quatro a oito inimigos: Leque de Facas com Ruptura com três pontos ou mais; nove ou mais: só Leque de Facas e Envenenar. A rotação integrada recomendada de Assassinato segue, em vez disso, as orientações mais novas da Fase 5; para usar esta, ative-a e desative a recomendada."
L["rm.mop.rogue.combat.Name"] = "Recomendada"
L["rm.mop.rogue.combat.Description"] = "Recomendada para Combate, do nível 10 ao 90 (Wowhead e simulador para a Fase 5). Desde o patch do Cerco a Orgrimmar, Golpe Sinistro custa 50 de energia, então Golpe Revelador é o gerador e Golpe Sinistro só é usado sob Sede de Sangue ou Heroísmo com Adrenalina (e antes do nível 20). Abre com Golpe Baixo quando solo, senão Emboscar. Mantém Retalhar ativo a partir de dois pontos e Golpe Revelador no alvo, gasta cinco pontos só enquanto Golpe Revelador estiver ativo (Retalhar, Ruptura em uma luta longa de alvo único sem Rajada de Lâminas, Eviscerar) e espera energia com cinco. Contra oito ou mais inimigos: Retalhar, Tempestade Carmesim e Leque de Facas. Solo, acrescenta Recobrar e Golpe no Rim. Lembretes: venenos, Chute, ativar Rajada de Lâminas contra dois ou mais inimigos e desativá-la depois, Adrenalina com pouca energia junto com Lâminas Sombrias, Matança, Sumir e Preparação para Emboscar durante Percepção Aguçada, Passo Furtivo, Evasão quando solo. Fica com você: Truques do Ofício e Expor Armadura (listados, mas desativados), Finta e o posicionamento atrás do alvo para Emboscar."
L["rm.mop.rogue.combat.hekili.Name"] = "Antecipação (Hekili)"
L["rm.mop.rogue.combat.hekili.Description"] = "Desativada por padrão. A ordem do Hekili para MoP para Combate com Antecipação: Golpe Revelador é o único gerador, mesmo sob Sede de Sangue; os finalizadores esperam Percepção Aguçada, quatro cargas de Antecipação ou o retorno de Lâminas Sombrias, depois Retalhar, Ruptura em um ou dois alvos que vão viver muito, Tempestade Carmesim com sete inimigos e Eviscerar; Retalhar é renovado mais cedo com 11 acúmulos de Logro do Bandido; Leque de Facas a partir de quatro inimigos. Só se aplica com o talento Antecipação. Ative-a e desative a rotação integrada recomendada de Combate para usá-la."
L["rm.mop.rogue.combat.icyveins.Name"] = "Golpe Sinistro como gerador (Icy Veins)"
L["rm.mop.rogue.combat.icyveins.Description"] = "Desativada por padrão, e superada na Fase 5. A ordem da Icy Veins, Warcraft Tavern, Method e wowtbc.gg de antes do patch do Cerco a Orgrimmar: Retalhar, Golpe Revelador mantido, Ruptura de cinco pontos em uma luta longa de alvo único e Eviscerar, com Golpe Sinistro como gerador. Os mesmos lembretes e jogo contra grupos de inimigos da rotação integrada recomendada de Combate. Escolha-a só se você segue esses guias; ative-a e desative a recomendada."
L["rm.mop.rogue.subtlety.Name"] = "Recomendada"
L["rm.mop.rogue.subtlety.Description"] = "Recomendada para Subterfúgio com Concentração Sombria, do nível 10 ao 90 (simulador e Wowhead para a Fase 5). Em Furtividade ou Dança das Sombras: Premeditação, Retalhar antes da puxada, finalizadores com cinco pontos, Emboscar, Garrote. Fora delas: Retalhar; com cinco pontos, Retalhar e Ruptura quando estiverem prestes a expirar, Eviscerar enquanto ambos durarem; Marcado para Morrer; Hemorragia para manter seu sangramento; Punhalada pelas Costas (com uma adaga) quando o alvo não está atacando você, senão Hemorragia. Contra três ou mais inimigos: Retalhar, Tempestade Carmesim, Eviscerar e Leque de Facas. Solo, acrescenta Recobrar e Golpe no Rim. Lembretes: venenos, Chute, Dança das Sombras com 75 de energia com Retalhar e Ruptura ativos, Sumir quando Achar Ponto Fraco estiver acabando, Preparação, Lâminas Sombrias fora de Dança e Furtividade, Passo Furtivo, Evasão quando solo. Fica com você: ficar atrás do alvo (o RM não consegue ver a orientação), Truques do Ofício e Expor Armadura (listados, mas desativados)."
L["rm.mop.rogue.subtlety.warcrafttavern.Name"] = "Subterfúgio (Warcraft Tavern)"
L["rm.mop.rogue.subtlety.warcrafttavern.Description"] = "Escolhida automaticamente no lugar da rotação integrada de Concentração Sombria quando seu talento do primeiro nível é Subterfúgio (a build da Warcraft Tavern). Premeditação e Retalhar antes da puxada; em Furtividade, Dança das Sombras ou no tempo extra de Subterfúgio, finalizadores com cinco pontos e depois Emboscar sempre que acertar. Dois ou três inimigos: mantém Ruptura ativa e gasta cinco pontos em Tempestade Carmesim em vez de Eviscerar; quatro ou mais acrescentam Leque de Facas. Um alvo: Retalhar, Ruptura, Eviscerar, Hemorragia pelo seu sangramento, Punhalada pelas Costas por trás com uma adaga, senão Hemorragia. Dança das Sombras e Sumir são lembretes com 60 de energia com Retalhar ativo; sincronizá-los com as ativações de berloques, como a Tavern sugere, fica por sua conta."
L["rm.mop.rogue.unspecialized.Name"] = "Sem especialização"
L["rm.mop.rogue.unspecialized.Description"] = "Para os níveis 1 a 9, ou um ladino que ainda não escolheu uma especialização; a rotação integrada de cada especialização assume assim que você escolhe uma. Abre a partir da Furtividade com Golpe Baixo quando solo, Emboscar ou Golpe Sinistro; sugere Furtividade fora de combate; Retalhar a partir de dois pontos, Recobrar e Golpe no Rim quando solo e ferido, Eviscerar com quatro pontos (dois quando o alvo estiver prestes a morrer), Golpe Sinistro. Lembretes: venenos depois de aprendidos, Chute, Evasão quando solo."
L["rm.retail.rogue.assassination.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.rogue.assassination.Description"] = "Recomendada para Assassinato no Midnight. Em combate, o jogo agora oculta seus sangramentos, bônus, energia, tempos de recarga e vida para addons, então esta rotação mostra a própria sugestão do Assistente de Combate da Blizzard (a rotação de um botão, que cuida da abertura em furtividade, Garrote, Ruptura, Envenenar, Marca da Morte e Ruína dos Reis), e para enquanto você lança ou não tem um inimigo como alvo. Lembretes do que ela deixa de fora: um veneno letal e um não letal e Furtividade entre os combates, Sumir quando você estiver fora da furtividade em combate, Chute em um lançamento interrompível (só acende onde o jogo permite ler o lançamento). A vida fica oculta no Retail, então Frasco Rubro fica por sua conta."
L["rm.retail.rogue.assassination.icyveins.Name"] = "Referência (Icy Veins)"
L["rm.retail.rogue.assassination.icyveins.Description"] = "Apenas referência, desativada por padrão: a ordem da Icy Veins e do SimulationCraft mantém os sangramentos pelos temporizadores, que o Midnight oculta em combate; a energia fica oculta no Retail, então o acúmulo de energia fica de fora. Em furtividade, Garrote e depois Emboscar. Garrote nos últimos 30% enquanto você não estiver com os pontos de combo no máximo, Ruptura com 5+ nos últimos 30%; com 5+ pontos de combo, Golpe de Misericórdia ou Envenenar; abaixo disso, Tempestade Carmesim contra três ou mais inimigos, Leque de Facas contra dois ou mais próximos, Emboscar, Mutilar. Lembretes: Marca da Morte com os dois sangramentos ativos, Ruína dos Reis junto com ela, Sumir com Marca da Morte pronta, Estocada em um alvo com Marca do Sicário, Chá de Cardo sempre que estiver pronto em combate, além dos lembretes compartilhados de veneno, Furtividade e Chute."
L["rm.retail.rogue.initial.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.rogue.initial.Description"] = "Recomendada antes de você escolher uma especialização (enquanto o jogo informa a especialização inicial do Ladino). Destaca o feitiço que o Assistente de Combate da Blizzard sugere em seguida, a única orientação de rotação que o jogo ainda deixa um addon ler em combate no Midnight; aguarda enquanto você lança ou canaliza. Junto a isso, os lembretes que toda rotação integrada de Ladino compartilha, cada um assim que você conhece o feitiço dele. Quando você escolhe uma especialização no nível 10, as rotações integradas dessa especialização assumem."
L["rm.retail.rogue.outlaw.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.rogue.outlaw.Description"] = "Recomendada para Fora da Lei no Midnight. Mostra a sugestão do Assistente de Combate da Blizzard (ela cuida da abertura em furtividade, Golpe de Sorte, Rajada de Lâminas, Adrenalina, No Meio da Testa e os finalizadores), e para enquanto você lança ou não tem um inimigo como alvo. Lembretes do que ela deixa de fora: venenos e Furtividade entre os combates, Sumir quando você estiver fora da furtividade em combate, Chute. A vida fica oculta no Retail, então Frasco Rubro fica por sua conta. Sorte Grande fica com você: o jogo oculta quantos bônus de Golpe de Sorte você tem."
L["rm.retail.rogue.outlaw.icyveins.Name"] = "Referência (Icy Veins)"
L["rm.retail.rogue.outlaw.icyveins.Description"] = "Apenas referência, desativada por padrão: a ordem da Icy Veins, do SimulationCraft e da Wowhead lê os bônus de Golpe de Sorte, os acúmulos de Oportunidade e a energia, que o Midnight oculta em combate. Em furtividade, Emboscar. Com pontos de combo a um do máximo ou mais: No Meio da Testa, Matança, Golpe de Misericórdia, Liquidar. Caso contrário, Emboscar com Audácia, Tiro de Pistola com seis acúmulos de Oportunidade (três com poucos pontos de combo), Emboscar, Golpe Sinistro. Lembretes: Golpe de Sorte sem nenhuma rolagem ativa, Adrenalina com dois pontos de combo ou menos, Rajada de Lâminas mantida contra dois ou mais inimigos, Ímpeto da Lâmina, Preparação quando Adrenalina, No Meio da Testa e Ímpeto da Lâmina estiverem todos em recarga. Sorte Grande continua manual."
L["rm.retail.rogue.subtlety.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.rogue.subtlety.Description"] = "Recomendada para Subterfúgio no Midnight. Mostra a sugestão do Assistente de Combate da Blizzard (ela cuida da abertura em furtividade, Lâminas Sombrias, Mordida do Gorjavil, Dança das Sombras, Técnica Secreta e os finalizadores), e para enquanto você lança ou não tem um inimigo como alvo. Lembretes do que ela deixa de fora: venenos e Furtividade entre os combates, Chute em um lançamento interrompível. A vida fica oculta no Retail, então Frasco Rubro fica por sua conta."
L["rm.retail.rogue.subtlety.icyveins.Name"] = "Referência (Icy Veins)"
L["rm.retail.rogue.subtlety.icyveins.Description"] = "Apenas referência, desativada por padrão: a ordem da Icy Veins e do SimulationCraft guarda Dança das Sombras para Técnica Secreta e lê Dança das Sombras, Noite Preta e energia, que o Midnight oculta em combate. Em furtividade antes da puxada: Golpe Sombrio. Com pontos de combo a um do máximo ou mais: Eviscerar com Noite Preta, Técnica Secreta durante Dança das Sombras, Golpe de Misericórdia, Pólvora Negra contra três ou mais inimigos, Eviscerar. Caso contrário, Golpe Sombrio, Tempestade de Shurikens contra dois ou mais, Lâmina Lúgubre ou Punhalada pelas Costas. Lembretes: Mordida do Gorjavil durante Dança das Sombras, Lâminas Sombrias com Dança das Sombras pronta, Dança das Sombras com dois pontos de combo ou menos (ou seis ou mais) quando Técnica Secreta estiver pronta ou Lâminas Sombrias estiver ativa, Sumir fora da furtividade com dois pontos de combo ou menos."
L["rm.sod.rogue.dps.Name"] = "DPS corpo a corpo (SoD)"
L["rm.sod.rogue.dps.Description"] = "Temporada da Descoberta, níveis 1–60 com as runas conforme você as grava; montada a partir do simulador Fase 6, Icy Veins e Zockify Fase 8. Em Furtividade: Golpe Sombrio, Garrote em grupo, Emboscar para uma build de Punhalada pelas Costas com uma adaga, Golpe Baixo quando solo. Contra três ou mais inimigos lutando com você: Bacamarte, Tempestade Carmesim, Leque de Facas primeiro. Depois Emboscar com uma ativação de Perfídia (com uma adaga), Talho de Sabre mantido em três acúmulos, Faca Envenenada com quatro acúmulos de veneno, Retalhar a partir de dois pontos (renovado a partir de quatro, a menos que Direto ao Ponto esteja gravado), a tarefa de Expor Armadura quando ninguém usa Fender Armadura nem mantém Veneno Sebáceo, com Chacina gravada um sangramento (Tempestade Carmesim, senão Ruptura; nenhum com Talho de Sabre), Envenenar com cinco (Eviscerar até você gravá-lo) e um gerador conforme a runa de luvas: Mutilar, Talho de Sabre, Punhalada pelas Costas (com uma adaga), senão Golpe Sinistro. Lembretes: um encantamento temporário em cada arma, Chute, Chá de Cardo, Rajada de Lâminas, Adrenalina, Sangue Frio e Evasão, e, com Mestre do Subterfúgio gravado, Sumir para renová-lo e Preparação."
L["rm.sod.rogue.dps.icyveins.Name"] = "DPS corpo a corpo, Ruptura para Chacina (SoD, Icy Veins)"
L["rm.sod.rogue.dps.icyveins.Description"] = "A ordem da Temporada da Descoberta da Icy Veins, uma alternativa à rotação integrada de DPS corpo a corpo da Temporada da Descoberta recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Todo finalizador com cinco pontos de combo, primeiro Retalhar quando ausente ou acabando, depois Ruptura mantida quando Chacina está gravada, depois Envenenar; Faca Envenenada só com cinco acúmulos de veneno; Bacamarte ou Leque de Facas contra três inimigos. As mesmas aberturas, geradores e lembretes da rotação integrada recomendada; a tarefa de Veneno Sebáceo fica com você."
L["rm.sod.rogue.dps.zockify.Name"] = "DPS corpo a corpo, Envenenar enxuto (SoD, Zockify)"
L["rm.sod.rogue.dps.zockify.Description"] = "A lista enxuta da Temporada da Descoberta da Zockify, uma alternativa à rotação integrada de DPS corpo a corpo da Temporada da Descoberta recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Sem sangramentos e sem Expor Armadura. Faca Envenenada com quatro acúmulos de veneno, Retalhar quando ausente (a partir de dois pontos, quatro com Talho de Sabre), Envenenar com cinco, depois o gerador da runa de luvas. A explosão de dano com Sumir e Sangue Frio fica com você."
L["rm.sod.rogue.tank.Name"] = "Tanque (SoD)"
L["rm.sod.rogue.tank.Description"] = "Tanque da Temporada da Descoberta, escolhida quando Só Um Arranhão está gravado; montada a partir do simulador Fase 6, Icy Veins, Zockify e Warcraft Tavern. Ripostar, Adaga de Bloqueio assim que sair do tempo de recarga, Dança de Lâminas a partir de um ponto de combo (renovada a partir de três), Retalhar a partir de três (renovado a partir de quatro), Leque de Facas, Tempestade Carmesim e Bacamarte contra três ou mais inimigos, Bacamarte enquanto Dança de Lâminas estiver ativa, Eviscerar com cinco com os dois bônus ativos, Faca Envenenada com pouca energia, depois Talho de Sabre, Mutilar ou Golpe Sinistro. Lembretes: Caçoar em grupo quando seu alvo ataca outra pessoa, Chute, Evasão abaixo de metade da vida, Rajada de Lâminas, Adrenalina, Chá de Cardo e venenos de arma (o da mão secundária só com uma arma na mão secundária). Passo Furtivo e a tarefa de Veneno Sebáceo ficam com você."
L["rm.tbc.rogue.dps.simulator.Name"] = "DPS corpo a corpo (simulador)"
L["rm.tbc.rogue.dps.simulator.Description"] = "Níveis 1–70, todas as especializações. Em furtividade: Premeditação, depois Golpe Baixo solo ou Garrote em grupo, caso contrário Emboscar (com uma adaga na mão principal). Em combate: Ripostar, Retalhar a partir de dois pontos de combo (renovado nos últimos dois segundos), Eviscerar em um alvo prestes a morrer e, com cinco pontos, Ruptura quando ela for durar (não enquanto Rajada de Lâminas atinge vários alvos), caso contrário Eviscerar. Gera pontos com Mutilar ou Punhalada pelas Costas (adaga) quando o alvo não está atacando você, caso contrário Hemorragia ou Golpe Sinistro. Lembra você de venenos ausentes, Chute, Rajada de Lâminas e Adrenalina, Sangue Frio e Evasão. Expor Armadura, Golpe no Rim, Finta, Sumir e o posicionamento ficam com você."
L["rm.tbc.rogue.dps.wowhead.Name"] = "DPS corpo a corpo (Wowhead)"
L["rm.tbc.rogue.dps.wowhead.Description"] = "Níveis 1–70, todas as especializações, seguindo a Wowhead. As mesmas aberturas em furtividade, geradores e lembretes da versão simulador, mas Retalhar começa a partir de um ponto de combo e todo finalizador de cinco pontos é Eviscerar: sem Ruptura. Expor Armadura, Golpe no Rim, Finta, Sumir e o posicionamento ficam com você. Uma alternativa à rotação integrada de DPS corpo a corpo do simulador recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela."
